DECLARE
  owner_id uuid := auth.uid();
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'cover_asset_discard requiere una sesión' USING ERRCODE = '42501';
  END IF;
  PERFORM biblib.account_write_allowed();
  DELETE FROM biblib.cover_assets AS a WHERE a.id = p_asset_id AND a.user_id = owner_id AND a.state = 'quarantine';
  RETURN FOUND;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  max_rows integer := greatest(1, least(coalesce(p_limit, 100), 1000));
  grace interval := greatest(0, coalesce(p_grace_seconds, 86400)) * interval '1 second';
  assets jsonb;
  objects jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'owner', c.user_id, 'key', c.storage_key, 'reason', c.reason)), '[]'::jsonb) INTO assets
  FROM (
    SELECT a.id, a.user_id, a.storage_key,
      CASE WHEN a.state = 'quarantine' THEN 'quarantine' WHEN a.expires_at IS NOT NULL AND a.expires_at <= now_at THEN 'license' ELSE 'unreferenced' END AS reason
    FROM biblib.cover_assets AS a
    WHERE (p_owner IS NULL OR a.user_id = p_owner) AND (
      (a.state = 'quarantine' AND a.expires_at <= now_at)
      OR (a.state <> 'quarantine' AND a.expires_at IS NOT NULL AND a.expires_at <= now_at)
      OR (a.state <> 'quarantine' AND a.updated_at <= now_at - grace
        AND NOT EXISTS (SELECT 1 FROM biblib.editions AS e WHERE e.user_id = a.user_id AND e.cover_asset_id = a.id)
        AND NOT EXISTS (SELECT 1 FROM biblib.library_snapshot_chunks AS sc CROSS JOIN LATERAL jsonb_array_elements(sc.payload) AS item
          WHERE sc.user_id = a.user_id AND sc.kind = 'books' AND item->>'cover_asset_id' = a.id::text)))
    ORDER BY a.updated_at
    LIMIT max_rows
  ) AS c;
  SELECT coalesce(jsonb_agg(jsonb_build_object('owner', split_part(o.name, '/', 1), 'key', o.name)), '[]'::jsonb) INTO objects
  FROM (
    SELECT so.name FROM storage.objects AS so
    WHERE so.bucket_id = 'biblib-covers' AND (p_owner IS NULL OR so.name LIKE p_owner::text || '/%')
      AND so.created_at <= now_at - interval '10 minutes'
      AND NOT EXISTS (SELECT 1 FROM biblib.cover_assets AS a WHERE a.storage_key = so.name AND a.state <> 'quarantine')
      AND NOT EXISTS (SELECT 1 FROM biblib.cover_assets AS a WHERE a.state = 'quarantine' AND a.expires_at > now_at
        AND a.storage_key IS NULL AND so.name = a.user_id::text || '/' || a.id::text || '/' || coalesce(a.upload_token, '') || '.webp')
    ORDER BY so.created_at
    LIMIT max_rows
  ) AS o;
  RETURN jsonb_build_object('assets', assets, 'objects', objects);
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  grace interval := greatest(0, coalesce(p_grace_seconds, 86400)) * interval '1 second';
  keys text[];
BEGIN
  PERFORM 1 FROM biblib.cover_assets AS a WHERE a.id = ANY(p_ids) AND (p_owner IS NULL OR a.user_id = p_owner) FOR UPDATE;
  UPDATE biblib.editions AS e SET cover_asset_id = NULL, updated_at = now_at
  FROM biblib.cover_assets AS a
  WHERE e.user_id = a.user_id AND e.cover_asset_id = a.id AND a.id = ANY(p_ids) AND (p_owner IS NULL OR a.user_id = p_owner)
    AND a.state <> 'quarantine' AND a.expires_at IS NOT NULL AND a.expires_at <= now_at;
  WITH removed AS (
    DELETE FROM biblib.cover_assets AS a
    WHERE a.id = ANY(p_ids) AND (p_owner IS NULL OR a.user_id = p_owner) AND (
      (a.state = 'quarantine' AND a.expires_at <= now_at)
      OR (a.state <> 'quarantine' AND a.expires_at IS NOT NULL AND a.expires_at <= now_at)
      OR (a.state <> 'quarantine' AND a.updated_at <= now_at - grace
        AND NOT EXISTS (SELECT 1 FROM biblib.editions AS e WHERE e.user_id = a.user_id AND e.cover_asset_id = a.id)
        AND NOT EXISTS (SELECT 1 FROM biblib.library_snapshot_chunks AS sc CROSS JOIN LATERAL jsonb_array_elements(sc.payload) AS item
          WHERE sc.user_id = a.user_id AND sc.kind = 'books' AND item->>'cover_asset_id' = a.id::text)))
    RETURNING a.storage_key
  )
  SELECT coalesce(array_agg(r.storage_key) FILTER (WHERE r.storage_key IS NOT NULL), '{}'::text[]) INTO keys FROM removed AS r;
  RETURN keys;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  deletion biblib.account_deletions%ROWTYPE;
  next_state text;
BEGIN
  SELECT * INTO deletion FROM biblib.account_deletions AS d WHERE d.user_id = p_owner FOR UPDATE;
  IF NOT FOUND OR deletion.state <> 'running' OR deletion.lease_token IS DISTINCT FROM p_token THEN
    RETURN 'lease_lost';
  END IF;
  next_state := CASE WHEN deletion.attempts >= greatest(1, coalesce(p_max_attempts, 5)) THEN 'failed' ELSE 'waiting_retry' END;
  UPDATE biblib.account_deletions AS d SET state = next_state,
    error_code = CASE WHEN p_error_code ~ '^[A-Z_]{1,64}$' THEN p_error_code ELSE 'UNEXPECTED' END,
    lease_token = NULL, lease_until = NULL,
    next_attempt_at = now_at + greatest(0, least(coalesce(p_retry_ms, 60000), 86400000)) * interval '1 millisecond', updated_at = now_at
  WHERE d.user_id = p_owner;
  RETURN next_state;
END;

DECLARE
  steps text[] := ARRAY['sessions', 'storage', 'covers', 'snapshots', 'staging', 'jobs', 'views', 'previews', 'operations', 'private_cache', 'product', 'media', 'copies', 'editions', 'works', 'shelves', 'state', 'auth', 'verify'];
  now_at timestamptz := clock_timestamp();
  lease interval := greatest(1000, least(coalesce(p_lease_ms, 60000), 600000)) * interval '1 millisecond';
  lease_row jsonb := biblib.account_deletion_lease(p_owner, p_token);
  step_index integer := array_position(steps, p_step);
  pending boolean;
BEGIN
  IF lease_row->>'step' IS DISTINCT FROM p_step OR step_index IS NULL OR p_step = 'verify' THEN
    RAISE EXCEPTION 'Paso de eliminación no válido' USING ERRCODE = 'BD004';
  END IF;
  pending := CASE p_step
    WHEN 'sessions' THEN false
    WHEN 'storage' THEN EXISTS (SELECT 1 FROM storage.objects AS so WHERE so.name LIKE p_owner::text || '/%' OR so.owner = p_owner)
    WHEN 'auth' THEN EXISTS (SELECT 1 FROM auth.users AS account WHERE account.id = p_owner)
    ELSE biblib.account_deletion_step_remaining(p_owner, p_step) > 0
  END;
  IF pending THEN
    RAISE EXCEPTION 'El paso % de la eliminación aún tiene recursos', p_step USING ERRCODE = 'BD004';
  END IF;
  UPDATE biblib.account_deletions AS d SET step = steps[step_index + 1], attempts = 0, error_code = NULL,
    counts = d.counts || CASE WHEN jsonb_typeof(p_counts) = 'object' THEN p_counts ELSE '{}'::jsonb END, lease_until = now_at + lease, updated_at = now_at
  WHERE d.user_id = p_owner;
  RETURN steps[step_index + 1];
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  lease interval := greatest(1000, least(coalesce(p_lease_ms, 60000), 600000)) * interval '1 millisecond';
  candidate uuid;
  deletion biblib.account_deletions%ROWTYPE;
BEGIN
  SELECT d.user_id INTO candidate FROM biblib.account_deletions AS d
  WHERE (p_owner IS NULL OR d.user_id = p_owner)
    AND ((d.state IN ('pending', 'waiting_retry') AND d.next_attempt_at <= now_at) OR (d.state = 'running' AND (d.lease_until IS NULL OR d.lease_until <= now_at)))
  ORDER BY d.next_attempt_at, d.user_id
  LIMIT 1 FOR UPDATE SKIP LOCKED;
  IF candidate IS NULL THEN
    RETURN NULL;
  END IF;
  UPDATE biblib.account_deletions AS d SET state = 'running', lease_token = gen_random_uuid(), lease_until = now_at + lease,
    fencing_number = d.fencing_number + 1, attempts = d.attempts + 1, updated_at = now_at
  WHERE d.user_id = candidate RETURNING * INTO deletion;
  RETURN jsonb_build_object('userId', deletion.user_id, 'step', deletion.step, 'token', deletion.lease_token, 'fence', deletion.fencing_number,
    'attempts', deletion.attempts, 'requestedAt', deletion.requested_at);
END;

DECLARE
  value text := regexp_replace(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g'), '^ | $', '', 'g');
BEGIN
  value := normalize(value, NFD);
  value := regexp_replace(value, '[nN]' || U&'\0303', U&'\E000', 'g');
  value := regexp_replace(value, '[' || U&'\0300' || '-' || U&'\036F' || ']', '', 'g');
  RETURN normalize(replace(lower(value), U&'\E000', 'ñ'), NFC);
END;

DECLARE
  deletion biblib.account_deletions%ROWTYPE;
BEGIN
  SELECT * INTO deletion FROM biblib.account_deletions AS d WHERE d.user_id = p_owner FOR UPDATE;
  IF NOT FOUND OR deletion.state <> 'running' OR deletion.lease_token IS DISTINCT FROM p_token OR deletion.lease_until IS NULL OR deletion.lease_until <= clock_timestamp() THEN
    RAISE EXCEPTION 'El worker de eliminación perdió su lease' USING ERRCODE = 'BD003';
  END IF;
  RETURN jsonb_build_object('step', deletion.step, 'attempts', deletion.attempts, 'fence', deletion.fencing_number);
END;

DECLARE
  max_rows integer := greatest(1, least(coalesce(p_limit, 500), 5000));
  lease_row jsonb := biblib.account_deletion_lease(p_owner, p_token);
  tables text[] := biblib.account_deletion_step_tables(p_step);
  item text;
  owner_column text;
  removed integer;
BEGIN
  IF lease_row->>'step' IS DISTINCT FROM p_step OR tables IS NULL THEN
    RAISE EXCEPTION 'Paso de eliminación no válido para este lote' USING ERRCODE = 'BD004';
  END IF;
  IF p_step = 'covers' THEN
    UPDATE biblib.editions AS e SET cover_asset_id = NULL, updated_at = clock_timestamp()
    WHERE e.user_id = p_owner AND e.id = ANY(ARRAY(SELECT x.id FROM biblib.editions AS x WHERE x.user_id = p_owner AND x.cover_asset_id IS NOT NULL LIMIT max_rows));
    GET DIAGNOSTICS removed = ROW_COUNT;
    IF removed > 0 THEN
      RETURN removed;
    END IF;
  END IF;
  FOREACH item IN ARRAY tables LOOP
    IF item = 'locations' THEN
      DELETE FROM biblib.locations AS t WHERE t.ctid = ANY(ARRAY(SELECT s.ctid FROM biblib.locations AS s WHERE s.user_id = p_owner
        AND NOT EXISTS (SELECT 1 FROM biblib.locations AS child WHERE child.user_id = s.user_id AND child.parent_id = s.id) LIMIT max_rows));
    ELSE
      SELECT CASE WHEN bool_or(a.attname = 'owner_id') THEN 'owner_id' ELSE 'user_id' END INTO owner_column
      FROM pg_attribute AS a WHERE a.attrelid = format('biblib.%I', item)::regclass AND a.attname IN ('owner_id', 'user_id') AND NOT a.attisdropped;
      EXECUTE format('DELETE FROM biblib.%I AS t WHERE t.ctid = ANY(ARRAY(SELECT s.ctid FROM biblib.%I AS s WHERE s.%I = $1 LIMIT $2))', item, item, owner_column)
        USING p_owner, max_rows;
    END IF;
    GET DIAGNOSTICS removed = ROW_COUNT;
    IF removed > 0 THEN
      RETURN removed;
    END IF;
  END LOOP;
  RETURN 0;
END;

DECLARE
  removed integer;
BEGIN
  DELETE FROM biblib.account_deletions AS d WHERE d.user_id = ANY(ARRAY(SELECT m.user_id FROM biblib.account_deletions AS m
    WHERE m.state = 'completed' AND m.purge_after <= clock_timestamp() ORDER BY m.purge_after LIMIT greatest(1, least(coalesce(p_limit, 500), 5000))));
  GET DIAGNOSTICS removed = ROW_COUNT;
  RETURN removed;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
BEGIN
  UPDATE biblib.account_deletions AS d SET lease_until = now_at + greatest(1000, least(coalesce(p_lease_ms, 60000), 600000)) * interval '1 millisecond', updated_at = now_at
  WHERE d.user_id = p_owner AND d.state = 'running' AND d.lease_token = p_token AND d.lease_until > now_at;
  RETURN FOUND;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
BEGIN
  IF (SELECT count(*) FROM biblib.cover_assets AS a WHERE a.user_id = p_owner AND a.state = 'quarantine' AND a.expires_at > now_at) >= 5 THEN
    RETURN 'quarantine';
  END IF;
  IF (SELECT count(*) FROM biblib.cover_assets AS a WHERE a.user_id = p_owner AND a.state <> 'quarantine') >= 500
    OR (SELECT coalesce(sum(a.bytes), 0) FROM biblib.cover_assets AS a WHERE a.user_id = p_owner AND a.state <> 'quarantine') >= 209715200 THEN
    RETURN 'stored';
  END IF;
  RETURN NULL;
END;

DECLARE
  found jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(jsonb_build_object('bucket', o.bucket_id, 'name', o.name) ORDER BY o.bucket_id, o.name), '[]'::jsonb) INTO found
  FROM (SELECT so.bucket_id, so.name FROM storage.objects AS so WHERE so.name LIKE p_owner::text || '/%' OR so.owner = p_owner
    ORDER BY so.bucket_id, so.name LIMIT greatest(1, least(coalesce(p_limit, 100), 1000))) AS o;
  RETURN found;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  lease_row jsonb := biblib.account_deletion_lease(p_owner, p_token);
  residue jsonb;
BEGIN
  IF lease_row->>'step' IS DISTINCT FROM 'verify' THEN
    RAISE EXCEPTION 'La eliminación no ha llegado a la verificación' USING ERRCODE = 'BD004';
  END IF;
  residue := biblib.account_residue(p_owner);
  IF (residue->>'rows')::integer > 0 OR (residue->>'objects')::integer > 0 OR (residue->>'account')::boolean THEN
    RAISE EXCEPTION 'Quedan recursos de la cuenta' USING ERRCODE = 'BD004';
  END IF;
  UPDATE biblib.account_deletions AS d SET state = 'completed', step = 'done', completed_at = now_at,
    purge_after = now_at + make_interval(days => greatest(1, least(coalesce(p_mark_days, 90), 3650))),
    counts = '{}'::jsonb, error_code = NULL, lease_token = NULL, lease_until = NULL, attempts = 0, updated_at = now_at
  WHERE d.user_id = p_owner;
  RETURN jsonb_build_object('completedAt', now_at);
END;

DECLARE
  affected integer;
BEGIN
  UPDATE biblib.cover_assets AS a SET state = 'restored', updated_at = clock_timestamp() WHERE a.state = 'ready';
  GET DIAGNOSTICS affected = ROW_COUNT;
  UPDATE biblib.cover_assets AS a SET upload_token = NULL, expires_at = least(a.expires_at, clock_timestamp()), updated_at = clock_timestamp()
  WHERE a.state = 'quarantine';
  RETURN affected;
END;

BEGIN
  IF EXISTS (SELECT 1 FROM biblib.editions AS e WHERE e.id = NEW.id)
    AND NOT EXISTS (SELECT 1 FROM biblib.copies AS c WHERE c.user_id = NEW.user_id AND c.edition_id = NEW.id) THEN
    RAISE EXCEPTION 'Una edición necesita al menos un ejemplar' USING ERRCODE = 'BM001';
  END IF;
  RETURN NULL;
END;

BEGIN
  IF NEW.cover_asset_id IS NOT NULL AND NEW.cover_asset_id IS DISTINCT FROM OLD.cover_asset_id AND NOT EXISTS (
    SELECT 1 FROM biblib.cover_assets AS a WHERE a.id = NEW.cover_asset_id AND a.user_id = NEW.user_id AND a.state = 'ready'
      AND (a.expires_at IS NULL OR a.expires_at > clock_timestamp())) THEN
    RAISE EXCEPTION 'La portada privada no está disponible' USING ERRCODE = 'BA001';
  END IF;
  RETURN NEW;
END;

BEGIN
  NEW.version := gen_random_uuid();
  RETURN NEW;
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  created boolean;
  expired integer := 0;
  deletion biblib.account_deletions%ROWTYPE;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'account_deletion_request requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF p_operation_key IS NULL OR length(p_operation_key) NOT BETWEEN 16 AND 128 THEN
    RAISE EXCEPTION 'Clave de operación no válida' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users AS account WHERE account.id = owner_id) THEN
    RAISE EXCEPTION 'La cuenta de la sesión no existe' USING ERRCODE = '42501';
  END IF;
  INSERT INTO biblib.library_state (user_id) VALUES (owner_id) ON CONFLICT (user_id) DO NOTHING;
  PERFORM 1 FROM biblib.library_state AS state WHERE state.user_id = owner_id FOR UPDATE;
  INSERT INTO biblib.account_deletions (user_id, operation_key, requested_at, next_attempt_at, updated_at)
  VALUES (owner_id, p_operation_key, now_at, now_at, now_at) ON CONFLICT (user_id) DO NOTHING;
  created := FOUND;
  IF created THEN
    INSERT INTO biblib.account_lifecycle AS lifecycle (user_id, state, changed_at) VALUES (owner_id, 'deleting', now_at)
    ON CONFLICT (user_id) DO UPDATE SET state = 'deleting', changed_at = excluded.changed_at;
    UPDATE biblib.library_jobs AS j
    SET state = 'expired', error_code = 'ACCOUNT_INACTIVE', lease_token = NULL, lease_until = NULL, version = gen_random_uuid(),
      finished_at = now_at, expires_at = now_at + interval '30 days', updated_at = now_at
    WHERE j.user_id = owner_id AND j.state IN ('queued', 'running', 'waiting_retry', 'needs_review', 'paused');
    GET DIAGNOSTICS expired = ROW_COUNT;
  END IF;
  SELECT * INTO deletion FROM biblib.account_deletions AS d WHERE d.user_id = owner_id;
  RETURN jsonb_build_object('state', deletion.state, 'step', deletion.step, 'requestedAt', deletion.requested_at, 'created', created, 'expiredJobs', expired);
END;

DECLARE
  affected integer;
BEGIN
  UPDATE biblib.account_deletions AS d SET state = 'pending', attempts = 0, next_attempt_at = clock_timestamp(), updated_at = clock_timestamp()
  WHERE d.state = 'failed' AND (p_owner IS NULL OR d.user_id = p_owner);
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;

DECLARE
  owner_id uuid := auth.uid();
  deletion biblib.account_deletions%ROWTYPE;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'account_deletion_status requiere una sesión' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO deletion FROM biblib.account_deletions AS d WHERE d.user_id = owner_id;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM auth.users AS account WHERE account.id = owner_id) THEN
    RETURN jsonb_build_object('state', 'none');
  END IF;
  RETURN jsonb_build_object('state', deletion.state, 'step', deletion.step, 'requestedAt', deletion.requested_at);
END;

DECLARE
  item text;
  owner_column text;
  found integer;
  total integer := 0;
BEGIN
  IF p_step = 'covers' THEN
    SELECT count(*)::integer INTO total FROM biblib.editions AS e WHERE e.user_id = p_owner AND e.cover_asset_id IS NOT NULL;
  END IF;
  FOREACH item IN ARRAY coalesce(biblib.account_deletion_step_tables(p_step), '{}'::text[]) LOOP
    SELECT CASE WHEN bool_or(a.attname = 'owner_id') THEN 'owner_id' ELSE 'user_id' END INTO owner_column
    FROM pg_attribute AS a WHERE a.attrelid = format('biblib.%I', item)::regclass AND a.attname IN ('owner_id', 'user_id') AND NOT a.attisdropped;
    EXECUTE format('SELECT count(*)::integer FROM biblib.%I WHERE %I = $1', item, owner_column) INTO found USING p_owner;
    total := total + found;
  END LOOP;
  RETURN total;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  mark_days interval := make_interval(days => greatest(1, least(coalesce(p_mark_days, 90), 3650)));
BEGIN
  IF EXISTS (SELECT 1 FROM auth.users AS account WHERE account.id = p_owner) THEN
    RAISE EXCEPTION 'La identidad suprimida sigue en el destino' USING ERRCODE = 'BD004';
  END IF;
  INSERT INTO biblib.account_deletions AS d (user_id, state, step, operation_key, requested_at, completed_at, purge_after, updated_at)
  VALUES (p_owner, 'completed', 'done', 'restore-suppression', coalesce(p_requested_at, now_at), now_at, now_at + mark_days, now_at)
  ON CONFLICT (user_id) DO UPDATE SET state = 'completed', step = 'done', completed_at = coalesce(d.completed_at, now_at),
    purge_after = greatest(coalesce(d.purge_after, now_at + mark_days), now_at + mark_days), counts = '{}'::jsonb, error_code = NULL,
    lease_token = NULL, lease_until = NULL, attempts = 0, updated_at = now_at;
  RETURN true;
END;

BEGIN
  RETURN EXISTS (SELECT 1 FROM auth.users AS account WHERE account.id = p_owner)
    AND NOT EXISTS (SELECT 1 FROM biblib.account_lifecycle AS lifecycle WHERE lifecycle.user_id = p_owner AND lifecycle.state <> 'active')
    AND NOT EXISTS (SELECT 1 FROM biblib.account_deletions AS deletion WHERE deletion.user_id = p_owner);
END;

DECLARE
  item record;
  found integer;
  total integer := 0;
  tables jsonb := '{}'::jsonb;
  objects integer;
BEGIN
  FOR item IN SELECT c.relname AS name, a.attname AS owner_column FROM pg_class AS c JOIN pg_namespace AS n ON n.oid = c.relnamespace
    JOIN pg_attribute AS a ON a.attrelid = c.oid
    WHERE n.nspname = 'biblib' AND c.relkind = 'r' AND c.relname <> 'account_deletions' AND a.attname IN ('user_id', 'owner_id') AND a.attnum > 0 AND NOT a.attisdropped
    ORDER BY c.relname
  LOOP
    EXECUTE format('SELECT count(*)::integer FROM biblib.%I WHERE %I = $1', item.name, item.owner_column) INTO found USING p_owner;
    IF found > 0 THEN
      tables := tables || jsonb_build_object(item.name, found);
      total := total + found;
    END IF;
  END LOOP;
  SELECT count(*)::integer INTO objects FROM storage.objects AS so WHERE so.name LIKE p_owner::text || '/%' OR so.owner = p_owner;
  RETURN jsonb_build_object('rows', total, 'tables', tables, 'objects', objects, 'account', EXISTS (SELECT 1 FROM auth.users AS account WHERE account.id = p_owner));
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  affected integer := 0;
BEGIN
  IF p_state NOT IN ('active', 'blocked') THEN
    RAISE EXCEPTION 'Estado de cuenta no válido' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM biblib.account_deletions AS deletion WHERE deletion.user_id = p_owner) THEN
    RAISE EXCEPTION 'La cuenta está en eliminación: su estado lo gestiona la supresión' USING ERRCODE = 'BD002';
  END IF;
  INSERT INTO biblib.account_lifecycle AS lifecycle (user_id, state, changed_at) VALUES (p_owner, p_state, now_at)
  ON CONFLICT (user_id) DO UPDATE SET state = excluded.state, changed_at = excluded.changed_at;
  IF p_state = 'blocked' THEN
    UPDATE biblib.library_jobs AS j
    SET state = 'expired', error_code = 'ACCOUNT_INACTIVE', lease_token = NULL, lease_until = NULL, version = gen_random_uuid(),
      finished_at = now_at, expires_at = now_at + interval '30 days', updated_at = now_at
    WHERE j.user_id = p_owner AND j.state IN ('queued', 'running', 'waiting_retry', 'needs_review', 'paused');
    GET DIAGNOSTICS affected = ROW_COUNT;
  END IF;
  RETURN affected;
END;

DECLARE
  owner_id uuid := auth.uid();
BEGIN
  IF owner_id IS NOT NULL AND (
    EXISTS (SELECT 1 FROM biblib.account_lifecycle AS lifecycle WHERE lifecycle.user_id = owner_id AND lifecycle.state = 'deleting')
    OR EXISTS (SELECT 1 FROM biblib.account_deletions AS deletion WHERE deletion.user_id = owner_id)) THEN
    RAISE EXCEPTION 'La cuenta se está eliminando y no admite cambios' USING ERRCODE = 'BD001';
  END IF;
  RETURN true;
END;

BEGIN
  DELETE FROM biblib.copies AS c WHERE c.user_id = OLD.user_id AND c.id = OLD.id;
  RETURN OLD;
END;

DECLARE
  copy_id uuid := coalesce(NEW.id, gen_random_uuid());
  target uuid := NEW.edition_id;
  candidate text := coalesce(NEW.isbn13, biblib.isbn13_normalize(NEW.isbn));
  legacy text := coalesce(NEW.legacy_identifier, CASE WHEN biblib.isbn13_normalize(NEW.isbn) IS NULL AND btrim(coalesce(NEW.isbn, '')) <> '' THEN NEW.isbn END);
  verification jsonb := coalesce(NEW.edition_verification, jsonb_build_object('isbnVerified', coalesce(NEW.catalogue->'isbnVerified' = 'true'::jsonb, false)));
BEGIN
  IF target IS NULL OR NOT EXISTS (SELECT 1 FROM biblib.editions AS e WHERE e.user_id = NEW.user_id AND e.id = target) THEN
    target := coalesce(target, copy_id);
    INSERT INTO biblib.editions (id, user_id, work_id, isbn13, title, subtitle, authors, publishers, publish_date, number_of_pages, language, identifiers, catalogue,
      cover_small, cover_medium, cover_large, cover_asset_id, created_at, updated_at)
    VALUES (target, NEW.user_id, NEW.work_id, candidate, NEW.title, NEW.subtitle, coalesce(NEW.authors, '[]'::jsonb), coalesce(NEW.publishers, '[]'::jsonb),
      coalesce(NEW.publish_date, ''), coalesce(NEW.number_of_pages, 0), NEW.language, coalesce(NEW.identifiers, '{}'::jsonb),
      coalesce(NEW.catalogue, '{"source":"import"}'::jsonb) - 'isbnVerified', coalesce(NEW.cover_small, '/default-book-cover.webp'),
      coalesce(NEW.cover_medium, '/default-book-cover.webp'), coalesce(NEW.cover_large, '/default-book-cover.webp'), NEW.cover_asset_id,
      coalesce(NEW.created_at, now()), coalesce(NEW.updated_at, now()));
  END IF;
  INSERT INTO biblib.copies (id, user_id, edition_id, status, shelf_id, edition_verification, legacy_identifier, created_at, updated_at)
  VALUES (copy_id, NEW.user_id, target, coalesce(NEW.status, 'unread'), NEW.shelf_id, verification, legacy, coalesce(NEW.created_at, now()), coalesce(NEW.updated_at, now()));
  SELECT b.* INTO NEW FROM biblib.books AS b WHERE b.id = copy_id;
  RETURN NEW;
END;

DECLARE
  shared integer;
  candidate text := NEW.isbn13;
  legacy text := NEW.legacy_identifier;
  verification jsonb := NEW.edition_verification;
  stamp timestamptz := CASE WHEN NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN NEW.updated_at ELSE now() END;
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.edition_id IS DISTINCT FROM OLD.edition_id THEN
    RAISE EXCEPTION 'La vista books no cambia el ejemplar, su dueño ni su edición' USING ERRCODE = '0A000';
  END IF;
  IF NEW.isbn IS DISTINCT FROM OLD.isbn THEN
    candidate := biblib.isbn13_normalize(NEW.isbn);
    legacy := CASE WHEN candidate IS NULL AND btrim(coalesce(NEW.isbn, '')) <> '' THEN NEW.isbn END;
  END IF;
  IF NEW.catalogue->'isbnVerified' IS DISTINCT FROM OLD.catalogue->'isbnVerified' AND NEW.edition_verification IS NOT DISTINCT FROM OLD.edition_verification THEN
    verification := OLD.edition_verification || jsonb_build_object('isbnVerified', coalesce(NEW.catalogue->'isbnVerified' = 'true'::jsonb, false));
  END IF;
  IF (candidate, NEW.title, NEW.subtitle, NEW.authors, NEW.publishers, NEW.publish_date, NEW.number_of_pages, NEW.catalogue - 'isbnVerified',
      NEW.cover_small, NEW.cover_medium, NEW.cover_large, NEW.cover_asset_id, NEW.work_id, NEW.language, NEW.identifiers)
    IS DISTINCT FROM (OLD.isbn13, OLD.title, OLD.subtitle, OLD.authors, OLD.publishers, OLD.publish_date, OLD.number_of_pages, OLD.catalogue - 'isbnVerified',
      OLD.cover_small, OLD.cover_medium, OLD.cover_large, OLD.cover_asset_id, OLD.work_id, OLD.language, OLD.identifiers) THEN
    SELECT count(*) INTO shared FROM biblib.copies AS c WHERE c.user_id = OLD.user_id AND c.edition_id = OLD.edition_id;
    IF shared > 1 THEN
      RAISE EXCEPTION 'La edición la comparten % ejemplares: cámbiala con el contrato de edición', shared USING ERRCODE = 'BM003';
    END IF;
    UPDATE biblib.editions AS e SET isbn13 = candidate, title = NEW.title, subtitle = NEW.subtitle, authors = NEW.authors, publishers = NEW.publishers,
      publish_date = NEW.publish_date, number_of_pages = NEW.number_of_pages, catalogue = NEW.catalogue - 'isbnVerified',
      cover_small = NEW.cover_small, cover_medium = NEW.cover_medium, cover_large = NEW.cover_large, cover_asset_id = NEW.cover_asset_id,
      work_id = NEW.work_id, language = NEW.language, identifiers = NEW.identifiers, updated_at = stamp
    WHERE e.user_id = OLD.user_id AND e.id = OLD.edition_id;
  END IF;
  -- Como en la tabla anterior, toda actualización renueva el token de la ficha aunque no cambie ningún dato.
  UPDATE biblib.copies AS c SET status = NEW.status, shelf_id = NEW.shelf_id, edition_verification = verification, legacy_identifier = legacy,
    created_at = NEW.created_at, updated_at = stamp
  WHERE c.user_id = OLD.user_id AND c.id = OLD.id;
  SELECT b.* INTO NEW FROM biblib.books AS b WHERE b.id = OLD.id;
  RETURN NEW;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  entry biblib.catalogue_cache%ROWTYPE;
  leased bigint;
BEGIN
  IF p_lease_ms IS NULL OR p_lease_ms NOT BETWEEN 1 AND 600000 THEN
    RAISE EXCEPTION 'Concesión no válida' USING ERRCODE = '22023';
  END IF;
  -- Una entrada ilegible se retira solo si sigue siendo la misma que se leyó.
  IF p_discard_fence IS NOT NULL THEN
    DELETE FROM biblib.catalogue_cache AS c
    WHERE c.provider = p_provider AND c.policy_version = p_policy_version AND c.credential_scope = p_scope
      AND c.schema_version = p_schema_version AND c.operation = p_operation AND c.canonical_key = p_key AND c.fence = p_discard_fence;
  END IF;
  IF p_use_cache THEN
    SELECT * INTO entry FROM biblib.catalogue_cache AS c
    WHERE c.provider = p_provider AND c.policy_version = p_policy_version AND c.credential_scope = p_scope
      AND c.schema_version = p_schema_version AND c.operation = p_operation AND c.canonical_key = p_key;
    IF FOUND AND entry.expires_at > now_at THEN
      RETURN jsonb_build_object('state', 'hit', 'status', entry.status, 'payload', entry.payload, 'fence', entry.fence::text, 'fetchedAt', entry.fetched_at, 'expiresAt', entry.expires_at);
    END IF;
  END IF;
  -- Solo se toma la concesión si no existe o si la anterior caducó (trabajador muerto o tardío).
  INSERT INTO biblib.catalogue_inflight AS f (provider, policy_version, credential_scope, schema_version, operation, canonical_key, fence, lease_expires_at)
  VALUES (p_provider, p_policy_version, p_scope, p_schema_version, p_operation, p_key, nextval('biblib.catalogue_fence_seq'), now_at + p_lease_ms * interval '1 millisecond')
  ON CONFLICT (provider, policy_version, credential_scope, schema_version, operation, canonical_key) DO UPDATE
    SET fence = excluded.fence, lease_expires_at = excluded.lease_expires_at, created_at = now_at
    WHERE f.lease_expires_at <= now_at
  RETURNING f.fence INTO leased;
  IF leased IS NULL THEN
    RETURN jsonb_build_object('state', 'pending');
  END IF;
  -- Otro trabajador pudo publicar entre la lectura y la concesión.
  IF p_use_cache THEN
    SELECT * INTO entry FROM biblib.catalogue_cache AS c
    WHERE c.provider = p_provider AND c.policy_version = p_policy_version AND c.credential_scope = p_scope
      AND c.schema_version = p_schema_version AND c.operation = p_operation AND c.canonical_key = p_key;
    IF FOUND AND entry.expires_at > now_at THEN
      DELETE FROM biblib.catalogue_inflight AS f
      WHERE f.provider = p_provider AND f.policy_version = p_policy_version AND f.credential_scope = p_scope
        AND f.schema_version = p_schema_version AND f.operation = p_operation AND f.canonical_key = p_key AND f.fence = leased;
      RETURN jsonb_build_object('state', 'hit', 'status', entry.status, 'payload', entry.payload, 'fence', entry.fence::text, 'fetchedAt', entry.fetched_at, 'expiresAt', entry.expires_at);
    END IF;
  END IF;
  RETURN jsonb_build_object('state', 'leased', 'fence', leased::text);
END;

DECLARE
  now_at timestamptz := clock_timestamp();
BEGIN
  DELETE FROM biblib.catalogue_inflight AS f
  WHERE f.provider = p_provider AND f.policy_version = p_policy_version AND f.credential_scope = p_scope
    AND f.schema_version = p_schema_version AND f.operation = p_operation AND f.canonical_key = p_key
    AND f.fence = p_fence AND f.lease_expires_at > now_at;
  IF NOT FOUND THEN
    DELETE FROM biblib.catalogue_inflight AS f
    WHERE f.provider = p_provider AND f.policy_version = p_policy_version AND f.credential_scope = p_scope
      AND f.schema_version = p_schema_version AND f.operation = p_operation AND f.canonical_key = p_key AND f.fence = p_fence;
    RETURN 'stale';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('found', 'notFound') OR p_ttl_ms IS NULL OR p_ttl_ms <= 0 OR p_payload IS NULL THEN
    RETURN 'released';
  END IF;
  INSERT INTO biblib.catalogue_cache AS c (provider, policy_version, credential_scope, schema_version, operation, canonical_key, status, payload, provenance, fence, fetched_at, expires_at)
  VALUES (p_provider, p_policy_version, p_scope, p_schema_version, p_operation, p_key, p_status, p_payload, coalesce(p_provenance, '{}'::jsonb), p_fence, now_at, now_at + least(p_ttl_ms, 86400000) * interval '1 millisecond')
  ON CONFLICT (provider, policy_version, credential_scope, schema_version, operation, canonical_key) DO UPDATE
    SET status = excluded.status, payload = excluded.payload, provenance = excluded.provenance, fence = excluded.fence,
      fetched_at = excluded.fetched_at, expires_at = excluded.expires_at
    WHERE c.fence < excluded.fence;
  IF FOUND THEN
    RETURN 'published';
  END IF;
  RETURN 'stale';
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  removed integer;
  counted integer;
BEGIN
  DELETE FROM biblib.catalogue_cache AS c WHERE c.provider = p_provider
    AND (p_policy_version IS NULL OR c.policy_version <> p_policy_version OR c.schema_version <> p_schema_version OR c.expires_at <= now_at);
  GET DIAGNOSTICS removed = ROW_COUNT;
  DELETE FROM biblib.catalogue_private_cache AS c WHERE c.provider = p_provider
    AND (p_policy_version IS NULL OR c.policy_version <> p_policy_version OR c.schema_version <> p_schema_version OR c.expires_at <= now_at);
  GET DIAGNOSTICS counted = ROW_COUNT;
  removed := removed + counted;
  DELETE FROM biblib.catalogue_inflight AS f WHERE f.provider = p_provider AND f.lease_expires_at <= now_at
    AND (p_policy_version IS NULL OR f.policy_version <> p_policy_version OR f.schema_version <> p_schema_version);
  RETURN removed;
END;

DECLARE
  entry biblib.catalogue_private_cache%ROWTYPE;
BEGIN
  SELECT * INTO entry FROM biblib.catalogue_private_cache AS c
  WHERE c.owner_id = p_owner AND c.provider = p_provider AND c.policy_version = p_policy_version AND c.credential_scope = p_scope
    AND c.schema_version = p_schema_version AND c.operation = p_operation AND c.key_hmac = p_key_hmac AND c.expires_at > clock_timestamp();
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object('status', entry.status, 'payload', entry.payload, 'fetchedAt', entry.fetched_at, 'expiresAt', entry.expires_at);
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  quota text;
  token text := replace(gen_random_uuid()::text, '-', '');
  asset_id uuid;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'cover_asset_begin_upload requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF NOT biblib.account_is_active(owner_id) THEN
    RETURN jsonb_build_object('status', 'inactive');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('biblib.library_jobs:' || owner_id::text, 0));
  quota := biblib.cover_asset_quota(owner_id);
  IF quota IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'quota', 'quota', quota);
  END IF;
  INSERT INTO biblib.cover_assets (user_id, state, source_kind, source_ref, rights_policy_version, upload_token, expires_at)
  VALUES (owner_id, 'quarantine', 'upload', 'upload', 'upload.v1', token, now_at + interval '15 minutes')
  RETURNING id INTO asset_id;
  RETURN jsonb_build_object('status', 'created', 'asset_id', asset_id, 'upload_token', token);
END;

DECLARE
  now_at timestamptz := clock_timestamp();
BEGIN
  IF p_owner IS NULL OR p_status IS NULL OR p_status NOT IN ('found', 'notFound') OR p_ttl_ms IS NULL OR p_ttl_ms <= 0 OR p_payload IS NULL THEN
    RETURN false;
  END IF;
  DELETE FROM biblib.catalogue_private_cache AS c WHERE c.ctid IN (
    SELECT old.ctid FROM biblib.catalogue_private_cache AS old WHERE old.owner_id = p_owner AND old.expires_at <= now_at LIMIT 100);
  INSERT INTO biblib.catalogue_private_cache AS c (owner_id, provider, policy_version, credential_scope, schema_version, operation, key_hmac, status, payload, fetched_at, expires_at)
  VALUES (p_owner, p_provider, p_policy_version, p_scope, p_schema_version, p_operation, p_key_hmac, p_status, p_payload, now_at, now_at + least(p_ttl_ms, 86400000) * interval '1 millisecond')
  ON CONFLICT (owner_id, provider, policy_version, credential_scope, schema_version, operation, key_hmac) DO UPDATE
    SET status = excluded.status, payload = excluded.payload, fetched_at = excluded.fetched_at, expires_at = excluded.expires_at
    WHERE c.fetched_at <= excluded.fetched_at;
  RETURN true;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  released biblib.catalogue_quota_reservations%ROWTYPE;
  cooldown timestamptz;
BEGIN
  UPDATE biblib.catalogue_quota_reservations AS r SET released_at = now_at
  WHERE r.id = p_reservation AND r.fence = p_fence AND r.released_at IS NULL
  RETURNING * INTO released;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF p_retry_after_ms > 0 THEN
    cooldown := now_at + least(p_retry_after_ms, 3600000) * interval '1 millisecond';
    UPDATE biblib.catalogue_quota_buckets AS b
    SET cooldown_until = greatest(b.cooldown_until, cooldown), next_slot_at = greatest(b.next_slot_at, cooldown), updated_at = now_at
    WHERE b.provider = released.provider AND b.credential_scope = released.credential_scope;
  END IF;
  RETURN true;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  bucket biblib.catalogue_quota_buckets%ROWTYPE;
  slot timestamptz;
  active integer;
  granted bigint;
  reservation uuid;
BEGIN
  IF p_purpose IS NULL OR p_purpose NOT IN ('interactive', 'batch') OR p_interval_ms NOT BETWEEN 1 AND 3600000
    OR p_horizon_ms NOT BETWEEN 0 AND 60000 OR p_owner_cap NOT BETWEEN 1 AND 100 OR p_lease_ms NOT BETWEEN 1 AND 600000 THEN
    RAISE EXCEPTION 'Parámetros de cuota no válidos' USING ERRCODE = '22023';
  END IF;
  INSERT INTO biblib.catalogue_quota_buckets (provider, credential_scope, interval_ms, next_slot_at)
  VALUES (p_provider, p_scope, p_interval_ms, now_at) ON CONFLICT (provider, credential_scope) DO NOTHING;
  SELECT * INTO bucket FROM biblib.catalogue_quota_buckets AS b
  WHERE b.provider = p_provider AND b.credential_scope = p_scope FOR UPDATE;
  -- Limpieza acotada de reservas antiguas; nunca toca las vigentes.
  DELETE FROM biblib.catalogue_quota_reservations AS r WHERE r.ctid IN (
    SELECT old.ctid FROM biblib.catalogue_quota_reservations AS old
    WHERE old.provider = p_provider AND old.credential_scope = p_scope AND old.expires_at < now_at - interval '1 hour' LIMIT 100);
  IF bucket.cooldown_until > now_at THEN
    RETURN jsonb_build_object('state', 'cooldown', 'retryMs', ceil(extract(epoch FROM bucket.cooldown_until - now_at) * 1000)::bigint);
  END IF;
  SELECT count(*) INTO active FROM biblib.catalogue_quota_reservations AS r
  WHERE r.provider = p_provider AND r.credential_scope = p_scope AND r.owner_id IS NOT DISTINCT FROM p_owner
    AND r.purpose = p_purpose AND r.released_at IS NULL AND r.expires_at > now_at;
  IF active >= p_owner_cap THEN
    RETURN jsonb_build_object('state', 'busy', 'retryMs', p_interval_ms);
  END IF;
  slot := greatest(now_at, bucket.next_slot_at);
  IF slot > now_at + p_horizon_ms * interval '1 millisecond' THEN
    RETURN jsonb_build_object('state', 'wait', 'retryMs', greatest(1, ceil(extract(epoch FROM slot - now_at) * 1000) - p_horizon_ms)::bigint);
  END IF;
  granted := nextval('biblib.catalogue_fence_seq');
  UPDATE biblib.catalogue_quota_buckets AS b
  SET interval_ms = p_interval_ms, next_slot_at = slot + p_interval_ms * interval '1 millisecond', updated_at = now_at
  WHERE b.provider = p_provider AND b.credential_scope = p_scope;
  INSERT INTO biblib.catalogue_quota_reservations (provider, credential_scope, owner_id, purpose, fence, slot_at, expires_at)
  VALUES (p_provider, p_scope, p_owner, p_purpose, granted, slot, slot + p_lease_ms * interval '1 millisecond')
  RETURNING id INTO reservation;
  RETURN jsonb_build_object('state', 'reserved', 'reservationId', reservation, 'fence', granted::text, 'waitMs', ceil(extract(epoch FROM slot - now_at) * 1000)::bigint);
END;

DECLARE
  owner_id uuid := auth.uid();
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'cover_asset_authorize requiere una sesión' USING ERRCODE = '42501';
  END IF;
  UPDATE biblib.cover_assets AS a SET upload_token = p_upload_token, updated_at = clock_timestamp()
  WHERE a.id = p_asset_id AND a.user_id = owner_id AND a.state = 'quarantine' AND a.expires_at > clock_timestamp()
    AND biblib.account_is_active(owner_id);
  RETURN FOUND;
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  asset biblib.cover_assets%ROWTYPE;
  key text;
  duplicate uuid;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'cover_asset_register requiere una sesión' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO asset FROM biblib.cover_assets AS a WHERE a.id = p_asset_id AND a.user_id = owner_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  IF NOT biblib.account_is_active(owner_id) THEN
    RETURN jsonb_build_object('status', 'inactive');
  END IF;
  IF asset.state <> 'quarantine' OR asset.expires_at <= now_at OR asset.upload_token IS DISTINCT FROM p_upload_token THEN
    RETURN jsonb_build_object('status', 'stale');
  END IF;
  SELECT a.id INTO duplicate FROM biblib.cover_assets AS a WHERE a.user_id = owner_id AND a.sha256 = p_sha256 AND a.state IN ('ready', 'restored') AND a.id <> asset.id;
  IF FOUND THEN
    DELETE FROM biblib.cover_assets AS a WHERE a.id = asset.id;
    RETURN jsonb_build_object('status', 'duplicate', 'asset_id', duplicate);
  END IF;
  key := owner_id::text || '/' || asset.id::text || '/' || p_upload_token || '.webp';
  IF NOT EXISTS (SELECT 1 FROM storage.objects AS o WHERE o.bucket_id = 'biblib-covers' AND o.name = key AND (o.metadata->>'size')::bigint = p_bytes) THEN
    RETURN jsonb_build_object('status', 'missing_object');
  END IF;
  UPDATE biblib.cover_assets AS a
  SET state = 'ready', storage_key = key, sha256 = p_sha256, mime = 'image/webp', bytes = p_bytes, width = p_width, height = p_height,
    upload_token = NULL, expires_at = p_license_expires_at, version = gen_random_uuid(), updated_at = now_at
  WHERE a.id = asset.id;
  RETURN jsonb_build_object('status', 'ready', 'asset_id', asset.id);
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  existing biblib.library_jobs%ROWTYPE;
  current_version uuid;
  quota text;
  job_id uuid;
  asset_id uuid;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'cover_asset_request requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF NOT biblib.account_is_active(owner_id) THEN
    RETURN jsonb_build_object('status', 'inactive');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('biblib.library_jobs:' || owner_id::text, 0));
  SELECT * INTO existing FROM biblib.library_jobs AS j WHERE j.user_id = owner_id AND j.kind = 'cover_asset' AND j.idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF existing.input_digest <> p_input_digest THEN
      RETURN jsonb_build_object('status', 'conflict');
    END IF;
    SELECT a.id INTO asset_id FROM biblib.cover_assets AS a WHERE a.job_id = existing.id AND a.user_id = owner_id;
    RETURN jsonb_build_object('status', 'existing', 'job_id', existing.id, 'asset_id', asset_id);
  END IF;
  SELECT b.version INTO current_version FROM biblib.books AS b WHERE b.id = p_book_id AND b.user_id = owner_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  IF current_version <> p_book_version THEN
    RETURN jsonb_build_object('status', 'stale');
  END IF;
  IF (SELECT count(*) FROM biblib.library_jobs AS j WHERE j.user_id = owner_id AND j.state IN ('queued', 'running', 'waiting_retry', 'paused')) >= 5 THEN
    RETURN jsonb_build_object('status', 'limit');
  END IF;
  quota := biblib.cover_asset_quota(owner_id);
  IF quota IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'quota', 'quota', quota);
  END IF;
  INSERT INTO biblib.library_jobs (user_id, kind, contract_version, idempotency_key, input_digest, phase, next_attempt_at, expires_at)
  VALUES (owner_id, 'cover_asset', 1, p_idempotency_key, p_input_digest, 'asset', now_at, now_at + interval '1 day')
  RETURNING id INTO job_id;
  INSERT INTO biblib.cover_assets (user_id, state, source_kind, source_ref, rights_policy_version, attribution, job_id, attach_book_id, attach_book_version, expires_at)
  VALUES (owner_id, 'quarantine', 'provider', p_source_ref, p_policy_version, p_attribution, job_id, p_book_id, p_book_version, now_at + interval '1 day')
  RETURNING id INTO asset_id;
  RETURN jsonb_build_object('status', 'created', 'job_id', job_id, 'asset_id', asset_id);
END;

DECLARE
  current_state text;
BEGIN
  SELECT s.state INTO current_state FROM biblib.import_sessions AS s
  WHERE s.id = NEW.session_id AND s.user_id = NEW.user_id AND s.expires_at > now();
  IF current_state IS DISTINCT FROM 'receiving' THEN
    RAISE EXCEPTION 'La sesión de restauración no admite más datos' USING ERRCODE = 'BR001';
  END IF;
  RETURN NEW;
END;

DECLARE
  owner_id uuid := auth.uid();
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'cover_asset_revalidate requiere una sesión' USING ERRCODE = '42501';
  END IF;
  PERFORM biblib.account_write_allowed();
  IF p_accept THEN
    UPDATE biblib.cover_assets AS a SET state = 'ready', version = gen_random_uuid(), updated_at = clock_timestamp()
    WHERE a.id = p_asset_id AND a.user_id = owner_id AND a.state = 'restored';
    RETURN CASE WHEN FOUND THEN 'ready' ELSE 'not_found' END;
  END IF;
  UPDATE biblib.editions AS e SET cover_asset_id = NULL, updated_at = clock_timestamp() WHERE e.user_id = owner_id AND e.cover_asset_id = p_asset_id;
  DELETE FROM biblib.cover_assets AS a WHERE a.id = p_asset_id AND a.user_id = owner_id AND a.state = 'restored';
  RETURN CASE WHEN FOUND THEN 'discarded' ELSE 'not_found' END;
END;

DECLARE
  owner_id uuid := auth.uid();
  parts text[];
  asset biblib.cover_assets%ROWTYPE;
BEGIN
  IF owner_id IS NULL OR p_name IS NULL OR p_action IS NULL OR p_action NOT IN ('select', 'insert', 'delete') THEN
    RETURN false;
  END IF;
  parts := string_to_array(p_name, '/');
  IF coalesce(array_length(parts, 1), 0) <> 3 OR parts[1] <> owner_id::text
    OR parts[2] !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR parts[3] !~ '^[A-Za-z0-9_-]{1,64}[.]webp$' THEN
    RETURN false;
  END IF;
  SELECT * INTO asset FROM biblib.cover_assets AS a WHERE a.id = parts[2]::uuid AND a.user_id = owner_id;
  IF NOT FOUND THEN
    -- Objeto propio sin fila (subido y nunca registrado, o asset ya purgado): solo se puede retirar.
    RETURN p_action = 'delete' AND biblib.account_is_active(owner_id);
  END IF;
  IF p_action = 'select' THEN
    RETURN true;
  END IF;
  IF p_action = 'delete' THEN
    RETURN biblib.account_is_active(owner_id) AND (asset.state = 'quarantine' OR asset.storage_key IS DISTINCT FROM p_name);
  END IF;
  RETURN asset.state = 'quarantine' AND asset.expires_at > clock_timestamp() AND asset.upload_token IS NOT NULL
    AND parts[3] = asset.upload_token || '.webp' AND biblib.account_is_active(owner_id)
    AND (asset.job_id IS NULL OR EXISTS (SELECT 1 FROM biblib.library_jobs AS j WHERE j.id = asset.job_id AND j.user_id = owner_id
      AND j.state = 'running' AND j.lease_until > clock_timestamp() AND j.fencing_number::text = asset.upload_token));
END;

BEGIN
  INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  VALUES ('biblib-covers', 'biblib-covers', false, 5242880, ARRAY['image/webp'])
  ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  DROP POLICY IF EXISTS "biblib_covers_select_own" ON storage.objects;
  DROP POLICY IF EXISTS "biblib_covers_insert_own" ON storage.objects;
  DROP POLICY IF EXISTS "biblib_covers_delete_own" ON storage.objects;
  CREATE POLICY "biblib_covers_select_own" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
    USING (bucket_id = 'biblib-covers' AND biblib.cover_object_access(name, 'select'));
  CREATE POLICY "biblib_covers_insert_own" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
    WITH CHECK (bucket_id = 'biblib-covers' AND biblib.cover_object_access(name, 'insert'));
  CREATE POLICY "biblib_covers_delete_own" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated
    USING (bucket_id = 'biblib-covers' AND biblib.cover_object_access(name, 'delete'));
END;

DECLARE
  max_rows integer := TG_ARGV[0]::integer;
  group_column text := CASE WHEN TG_NARGS > 1 THEN TG_ARGV[1] END;
  group_value text;
  total integer;
BEGIN
  IF group_column IS NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(format('biblib.%s:%s', TG_TABLE_NAME, NEW.user_id), 0));
    EXECUTE format('SELECT count(*)::integer FROM biblib.%I AS t WHERE t.user_id = $1', TG_TABLE_NAME) INTO total USING NEW.user_id;
  ELSE
    group_value := to_jsonb(NEW)->>group_column;
    PERFORM pg_advisory_xact_lock(hashtextextended(format('biblib.%s:%s:%s', TG_TABLE_NAME, NEW.user_id, group_value), 0));
    EXECUTE format('SELECT count(*)::integer FROM biblib.%I AS t WHERE t.user_id = $1 AND t.%I::text = $2', TG_TABLE_NAME, group_column) INTO total USING NEW.user_id, group_value;
  END IF;
  IF total >= max_rows THEN
    RAISE EXCEPTION 'Límite alcanzado en % (%)', TG_TABLE_NAME, max_rows USING ERRCODE = 'BP001';
  END IF;
  RETURN NEW;
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  captured uuid;
  new_id uuid;
  book_total integer;
  shelf_total integer;
  tag_total integer;
  location_total integer;
  series_total integer;
  cycle_total integer;
  entry_total integer;
  loan_total integer;
  shelf_chunks integer;
  book_chunks integer;
  tag_chunks integer;
  location_chunks integer;
  chunk_total integer;
  byte_total bigint;
  final_digest text;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'library_snapshot_capture requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF p_reason NOT IN ('import.replace', 'snapshot.restore') THEN
    RAISE EXCEPTION 'Motivo de captura no válido' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM biblib.library_operations AS o WHERE o.id = p_operation_id AND o.user_id = owner_id AND o.created_at = now()) THEN
    RAISE EXCEPTION 'La captura exige la operación de esta misma transacción' USING ERRCODE = '42501';
  END IF;
  IF NOT biblib.account_is_active(owner_id) THEN
    RAISE EXCEPTION 'La cuenta no admite versiones nuevas' USING ERRCODE = 'BS002';
  END IF;
  captured := biblib.lock_library();
  DELETE FROM biblib.library_snapshots AS s WHERE s.user_id = owner_id AND s.expires_at <= now_at;
  IF (SELECT count(*) FROM biblib.library_snapshots AS s WHERE s.user_id = owner_id) >= 10 THEN
    RAISE EXCEPTION 'Cuota de versiones anteriores agotada' USING ERRCODE = 'BS001';
  END IF;
  SELECT count(*) INTO book_total FROM biblib.copies AS c WHERE c.user_id = owner_id;
  SELECT count(*) INTO shelf_total FROM biblib.shelves AS sh WHERE sh.user_id = owner_id;
  SELECT count(*) INTO tag_total FROM biblib.tags AS t WHERE t.user_id = owner_id;
  SELECT count(*) INTO location_total FROM biblib.locations AS l WHERE l.user_id = owner_id;
  SELECT count(*) INTO series_total FROM biblib.series AS se WHERE se.user_id = owner_id;
  SELECT count(*) INTO cycle_total FROM biblib.reading_cycles AS r WHERE r.user_id = owner_id;
  SELECT count(*) INTO entry_total FROM biblib.reading_entries AS r WHERE r.user_id = owner_id;
  SELECT count(*) INTO loan_total FROM biblib.loans AS l WHERE l.user_id = owner_id;
  IF book_total > 10000 OR shelf_total > 1000 THEN
    RAISE EXCEPTION 'Colección demasiado grande para guardar una versión anterior' USING ERRCODE = 'BS003';
  END IF;
  INSERT INTO biblib.library_snapshots AS s (user_id, source_operation_id, reason, captured_revision, schema_version, state, expires_at, created_at)
  VALUES (owner_id, p_operation_id, p_reason, captured, 4, 'capturing', now_at + interval '30 days', now_at)
  RETURNING s.id INTO new_id;
  shelf_chunks := (shelf_total + 199) / 200;
  book_chunks := (book_total + 199) / 200;
  tag_chunks := (tag_total + 199) / 200;
  location_chunks := (location_total + 199) / 200;
  INSERT INTO biblib.library_snapshot_chunks (snapshot_id, user_id, seq, kind, item_count, payload, digest)
  SELECT new_id, owner_id, grouped.seq, grouped.kind, grouped.n, grouped.payload, encode(sha256(convert_to(grouped.payload::text, 'UTF8')), 'hex')
  FROM (
    SELECT (ranked.rn / 200)::integer AS seq, 'shelves'::text AS kind, count(*)::integer AS n, jsonb_agg(ranked.item ORDER BY ranked.rn) AS payload
    FROM (
      SELECT row_number() OVER (ORDER BY sh.created_at, sh.id) - 1 AS rn,
        jsonb_build_object('id', sh.id, 'title', sh.title, 'is_default', sh.is_default, 'created_at', sh.created_at) AS item
      FROM biblib.shelves AS sh WHERE sh.user_id = owner_id
    ) AS ranked
    GROUP BY ranked.rn / 200
    UNION ALL
    SELECT shelf_chunks + (ranked.rn / 200)::integer, 'books', count(*)::integer, jsonb_agg(ranked.item ORDER BY ranked.rn)
    FROM (
      SELECT row_number() OVER (ORDER BY b.id) - 1 AS rn,
        jsonb_build_object('id', b.id, 'isbn', b.isbn13, 'title', b.title, 'subtitle', b.subtitle, 'authors', b.authors, 'publishers', b.publishers,
          'catalogue', b.catalogue, 'number_of_pages', b.number_of_pages, 'publish_date', b.publish_date, 'cover_small', b.cover_small,
          'cover_medium', b.cover_medium, 'cover_large', b.cover_large, 'status', b.status, 'shelf_id', b.shelf_id, 'created_at', b.created_at,
          'edition_id', b.edition_id, 'verification', b.edition_verification)
          || CASE WHEN b.cover_asset_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('cover_asset_id', b.cover_asset_id) END
          || CASE WHEN b.legacy_identifier IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('legacy_identifier', b.legacy_identifier) END
          || CASE WHEN b.work_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('work_id', b.work_id, 'work_title', b.work_title) END
          || CASE WHEN b.language IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('language', b.language) END
          || CASE WHEN b.identifiers = '{}'::jsonb THEN '{}'::jsonb ELSE jsonb_build_object('identifiers', b.identifiers) END
          || CASE WHEN ann.notes IS NULL AND ann.rating IS NULL AND ct.tag_ids IS NULL THEN '{}'::jsonb
            ELSE jsonb_build_object('personal', jsonb_strip_nulls(jsonb_build_object('notes', ann.notes, 'rating', ann.rating, 'tag_ids', ct.tag_ids))) END
          || CASE WHEN cl.location_id IS NULL THEN '{}'::jsonb
            ELSE jsonb_build_object('location', jsonb_strip_nulls(jsonb_build_object('location_id', cl.location_id, 'shelf_label', cl.shelf_label, 'position', cl.position))) END
          || CASE WHEN se.series_id IS NULL THEN '{}'::jsonb
            ELSE jsonb_build_object('series', jsonb_strip_nulls(jsonb_build_object('series_id', se.series_id, 'position', trim_scale(se.position)::text, 'volume_label', se.volume_label, 'order_note', se.order_note))) END
          || CASE WHEN ce.items IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('evidence', ce.items) END
          || CASE WHEN ee.items IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('edition_evidence', ee.items) END
          || CASE WHEN rc.items IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('reading', rc.items) END
          || CASE WHEN lo.items IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('loans', lo.items) END AS item
      FROM biblib.books AS b
      LEFT JOIN biblib.copy_annotations AS ann ON ann.user_id = b.user_id AND ann.copy_id = b.id
      LEFT JOIN LATERAL (SELECT jsonb_agg(t.tag_id ORDER BY t.tag_id) AS tag_ids FROM biblib.copy_tags AS t WHERE t.user_id = b.user_id AND t.copy_id = b.id) AS ct ON true
      LEFT JOIN biblib.copy_locations AS cl ON cl.user_id = b.user_id AND cl.copy_id = b.id
      LEFT JOIN biblib.series_editions AS se ON se.user_id = b.user_id AND se.edition_id = b.edition_id
      LEFT JOIN LATERAL (SELECT jsonb_agg(biblib.evidence_snapshot_item(ev) ORDER BY ev.created_at, ev.id) AS items
        FROM biblib.bibliographic_evidence AS ev WHERE ev.user_id = b.user_id AND ev.copy_id = b.id) AS ce ON true
      LEFT JOIN LATERAL (SELECT jsonb_agg(biblib.evidence_snapshot_item(ev) ORDER BY ev.created_at, ev.id) AS items
        FROM biblib.bibliographic_evidence AS ev WHERE ev.user_id = b.user_id AND ev.edition_id = b.edition_id) AS ee ON true
      LEFT JOIN LATERAL (SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', cy.id, 'cycle_number', cy.cycle_number, 'status', cy.status,
            'started_at', cy.started_at, 'finished_at', cy.finished_at))
          || CASE WHEN en.items IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('entries', en.items) END ORDER BY cy.cycle_number, cy.id) AS items
        FROM biblib.reading_cycles AS cy
        LEFT JOIN LATERAL (SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', re.id, 'occurred_at', re.occurred_at, 'page_from', re.page_from,
            'page_to', re.page_to, 'note', re.note)) ORDER BY re.occurred_at, re.id) AS items
          FROM biblib.reading_entries AS re WHERE re.user_id = cy.user_id AND re.cycle_id = cy.id) AS en ON true
        WHERE cy.user_id = b.user_id AND cy.copy_id = b.id) AS rc ON true
      LEFT JOIN LATERAL (SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', l.id, 'borrower_label', l.borrower_label, 'loaned_on', l.loaned_on,
          'due_on', l.due_on, 'returned_on', l.returned_on, 'note', l.note)) ORDER BY l.loaned_on, l.created_at, l.id) AS items
        FROM biblib.loans AS l WHERE l.user_id = b.user_id AND l.copy_id = b.id) AS lo ON true
      WHERE b.user_id = owner_id
    ) AS ranked
    GROUP BY ranked.rn / 200
    UNION ALL
    SELECT shelf_chunks + book_chunks + (ranked.rn / 200)::integer, 'tags', count(*)::integer, jsonb_agg(ranked.item ORDER BY ranked.rn)
    FROM (
      SELECT row_number() OVER (ORDER BY t.created_at, t.id) - 1 AS rn, jsonb_build_object('id', t.id, 'name', t.name, 'created_at', t.created_at) AS item
      FROM biblib.tags AS t WHERE t.user_id = owner_id
    ) AS ranked
    GROUP BY ranked.rn / 200
    UNION ALL
    SELECT shelf_chunks + book_chunks + tag_chunks + (ranked.rn / 200)::integer, 'locations', count(*)::integer, jsonb_agg(ranked.item ORDER BY ranked.rn)
    FROM (
      SELECT row_number() OVER (ORDER BY l.created_at, l.id) - 1 AS rn,
        jsonb_build_object('id', l.id, 'parent_id', l.parent_id, 'name', l.name, 'kind', l.kind, 'photo_asset_id', l.photo_asset_id, 'created_at', l.created_at) AS item
      FROM biblib.locations AS l WHERE l.user_id = owner_id
    ) AS ranked
    GROUP BY ranked.rn / 200
    UNION ALL
    SELECT shelf_chunks + book_chunks + tag_chunks + location_chunks + (ranked.rn / 200)::integer, 'series', count(*)::integer, jsonb_agg(ranked.item ORDER BY ranked.rn)
    FROM (
      SELECT row_number() OVER (ORDER BY se.created_at, se.id) - 1 AS rn,
        jsonb_build_object('id', se.id, 'title', se.title, 'description', se.description, 'created_at', se.created_at) AS item
      FROM biblib.series AS se WHERE se.user_id = owner_id
    ) AS ranked
    GROUP BY ranked.rn / 200
  ) AS grouped;
  SELECT count(*)::integer, coalesce(sum(octet_length(c.payload::text)), 0),
    encode(sha256(convert_to(concat_ws('|', 'biblib.snapshot.v1', book_total, shelf_total, coalesce(string_agg(c.digest, '' ORDER BY c.seq), '')), 'UTF8')), 'hex')
  INTO chunk_total, byte_total, final_digest
  FROM biblib.library_snapshot_chunks AS c WHERE c.snapshot_id = new_id;
  UPDATE biblib.library_snapshots AS s
  SET state = 'ready', digest = final_digest,
    counts = jsonb_build_object('books', book_total, 'shelves', shelf_total, 'tags', tag_total, 'locations', location_total, 'series', series_total,
      'reading_cycles', cycle_total, 'reading_entries', entry_total, 'loans', loan_total, 'chunks', chunk_total, 'bytes', byte_total)
  WHERE s.id = new_id;
  RETURN jsonb_build_object('id', new_id, 'digest', final_digest, 'books', book_total, 'shelves', shelf_total, 'chunks', chunk_total);
END;

DECLARE
  cursor_id uuid;
  depth integer := 1;
  below integer;
BEGIN
  IF TG_WHEN = 'BEFORE' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('biblib.locations:' || NEW.user_id::text, 0));
    RETURN NEW;
  END IF;
  cursor_id := NEW.parent_id;
  WHILE cursor_id IS NOT NULL LOOP
    IF cursor_id = NEW.id THEN
      RAISE EXCEPTION 'Una ubicación no puede estar dentro de sí misma' USING ERRCODE = 'BL001';
    END IF;
    depth := depth + 1;
    IF depth > 8 THEN
      RAISE EXCEPTION 'Las ubicaciones admiten como máximo 8 niveles' USING ERRCODE = 'BL002';
    END IF;
    SELECT l.parent_id INTO cursor_id FROM biblib.locations AS l WHERE l.user_id = NEW.user_id AND l.id = cursor_id;
  END LOOP;
  WITH RECURSIVE subtree(id, level) AS (
    SELECT NEW.id, 0
    UNION ALL
    SELECT l.id, s.level + 1 FROM biblib.locations AS l JOIN subtree AS s ON l.parent_id = s.id
    WHERE l.user_id = NEW.user_id AND s.level < 8
  )
  SELECT max(s.level) INTO below FROM subtree AS s;
  IF depth + coalesce(below, 0) > 8 THEN
    RAISE EXCEPTION 'Las ubicaciones admiten como máximo 8 niveles' USING ERRCODE = 'BL002';
  END IF;
  RETURN NULL;
END;

DECLARE
  asset_id uuid := (to_jsonb(NEW)->>TG_ARGV[0])::uuid;
BEGIN
  IF asset_id IS NULL OR (TG_OP = 'UPDATE' AND asset_id IS NOT DISTINCT FROM (to_jsonb(OLD)->>TG_ARGV[0])::uuid) THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM biblib.media_assets AS a WHERE a.id = asset_id AND a.user_id = NEW.user_id AND a.kind = TG_ARGV[1] AND a.state = 'ready') THEN
    RAISE EXCEPTION 'La imagen privada no está disponible' USING ERRCODE = 'BA010';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('biblib.saved_views:' || NEW.user_id::text, 0));
    IF (SELECT count(*) FROM biblib.saved_book_views WHERE user_id = NEW.user_id) >= 100 THEN
      RAISE EXCEPTION 'Máximo de 100 vistas por cuenta' USING ERRCODE = 'BV001';
    END IF;
  ELSE
    IF NEW.user_id <> OLD.user_id OR NEW.id <> OLD.id THEN
      RAISE EXCEPTION 'No se puede transferir una vista' USING ERRCODE = '23514';
    END IF;
    NEW.created_at := OLD.created_at;
    NEW.updated_at := clock_timestamp();
  END IF;
  NEW.version := gen_random_uuid();
  RETURN NEW;
END;

DECLARE
  removed integer;
BEGIN
  DELETE FROM biblib.import_sessions AS s
  WHERE s.id IN (SELECT e.id FROM biblib.import_sessions AS e WHERE e.expires_at <= clock_timestamp() ORDER BY e.expires_at LIMIT greatest(1, least(coalesce(p_limit, 100), 1000)));
  GET DIAGNOSTICS removed = ROW_COUNT;
  RETURN removed;
END;

DECLARE
  digits text := upper(regexp_replace(coalesce(p_value, ''), '[[:space:]-]', '', 'g'));
  total integer := 0;
  prefix text;
BEGIN
  IF digits ~ '^[0-9]{9}[0-9X]$' THEN
    FOR i IN 1..10 LOOP
      total := total + (CASE WHEN substr(digits, i, 1) = 'X' THEN 10 ELSE substr(digits, i, 1)::integer END) * (11 - i);
    END LOOP;
    IF total % 11 <> 0 THEN
      RETURN NULL;
    END IF;
    prefix := '978' || substr(digits, 1, 9);
    total := 0;
    FOR i IN 1..12 LOOP
      total := total + substr(prefix, i, 1)::integer * (CASE WHEN i % 2 = 0 THEN 3 ELSE 1 END);
    END LOOP;
    RETURN prefix || ((10 - total % 10) % 10)::text;
  END IF;
  IF digits !~ '^97[89][0-9]{10}$' THEN
    RETURN NULL;
  END IF;
  FOR i IN 1..13 LOOP
    total := total + substr(digits, i, 1)::integer * (CASE WHEN i % 2 = 0 THEN 3 ELSE 1 END);
  END LOOP;
  RETURN CASE WHEN total % 10 = 0 THEN digits END;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  lease_ms integer := greatest(1000, least(coalesce(p_lease_ms, 60000), 300000));
  candidate biblib.library_jobs%ROWTYPE;
  claimed biblib.library_jobs%ROWTYPE;
  active boolean;
BEGIN
  FOR candidate IN
    SELECT * FROM biblib.library_jobs AS j
    WHERE (p_job_id IS NULL OR j.id = p_job_id) AND (p_owner IS NULL OR j.user_id = p_owner)
      -- U-DAT-10: una adquisición de portada sube con la sesión del dueño; el ejecutor sin sesión no la reclama.
      AND (p_job_id IS NOT NULL OR j.kind <> 'cover_asset')
      AND j.state IN ('queued', 'running', 'waiting_retry') AND j.next_attempt_at <= now_at
      AND (j.state <> 'running' OR j.lease_until <= now_at)
    ORDER BY j.next_attempt_at, j.created_at
    LIMIT 10
    FOR UPDATE SKIP LOCKED
  LOOP
    active := biblib.account_is_active(candidate.user_id);
    -- Caducado, cuenta no activa o pasos que fallan una y otra vez: se cierra sin ejecutar.
    IF candidate.expires_at <= now_at OR NOT active OR candidate.attempts >= 10 THEN
      UPDATE biblib.library_jobs AS j
      SET state = CASE WHEN candidate.expires_at <= now_at OR NOT active THEN 'expired' ELSE 'failed' END,
        error_code = CASE WHEN candidate.expires_at <= now_at THEN 'JOB_EXPIRED' WHEN NOT active THEN 'ACCOUNT_INACTIVE' ELSE 'STEP_FAILED' END,
        lease_token = NULL, lease_until = NULL, version = gen_random_uuid(), finished_at = now_at, expires_at = now_at + interval '30 days', updated_at = now_at
      WHERE j.id = candidate.id;
      CONTINUE;
    END IF;
    UPDATE biblib.library_jobs AS j
    SET state = 'running', lease_token = gen_random_uuid(), lease_until = now_at + lease_ms * interval '1 millisecond',
      fencing_number = nextval('biblib.library_job_fence_seq'), attempts = j.attempts + 1, updated_at = now_at
    WHERE j.id = candidate.id
    RETURNING * INTO claimed;
    RETURN to_jsonb(claimed) || jsonb_build_object('fencing_number', claimed.fencing_number::text);
  END LOOP;
  RETURN NULL;
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz;
  job biblib.library_jobs%ROWTYPE;
  target text;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'library_job_control requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF p_action NOT IN ('pause', 'resume', 'cancel') THEN
    RAISE EXCEPTION 'Acción de trabajo no válida' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO job FROM biblib.library_jobs AS j WHERE j.id = p_job_id AND j.user_id = owner_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  now_at := clock_timestamp();
  IF job.state IN ('queued', 'running', 'waiting_retry', 'needs_review', 'paused') AND (job.expires_at <= now_at OR NOT biblib.account_is_active(owner_id)) THEN
    UPDATE biblib.library_jobs AS j
    SET state = 'expired', error_code = CASE WHEN job.expires_at <= now_at THEN 'JOB_EXPIRED' ELSE 'ACCOUNT_INACTIVE' END,
      lease_token = NULL, lease_until = NULL, version = gen_random_uuid(), finished_at = now_at, expires_at = now_at + interval '30 days', updated_at = now_at
    WHERE j.id = job.id;
    RETURN jsonb_build_object('status', 'expired', 'published', job.published_at IS NOT NULL);
  END IF;
  IF job.state = 'expired' THEN
    RETURN jsonb_build_object('status', 'expired', 'published', job.published_at IS NOT NULL);
  END IF;
  IF job.version <> p_expected_version THEN
    RETURN jsonb_build_object('status', 'conflict');
  END IF;
  target := CASE
    WHEN p_action = 'pause' AND job.state IN ('queued', 'running', 'waiting_retry') THEN 'paused'
    WHEN p_action = 'resume' AND job.state = 'paused' THEN 'queued'
    WHEN p_action = 'cancel' AND job.state IN ('queued', 'running', 'waiting_retry', 'needs_review', 'paused') THEN 'cancelled'
  END;
  IF target IS NULL THEN
    IF (p_action = 'pause' AND job.state = 'paused') OR (p_action = 'resume' AND job.state IN ('queued', 'running', 'waiting_retry')) OR (p_action = 'cancel' AND job.state = 'cancelled') THEN
      RETURN jsonb_build_object('status', 'ok', 'published', job.published_at IS NOT NULL);
    END IF;
    RETURN jsonb_build_object('status', 'conflict');
  END IF;
  UPDATE biblib.library_jobs AS j
  SET state = target, version = gen_random_uuid(), lease_token = NULL, lease_until = NULL,
    next_attempt_at = CASE WHEN target = 'queued' THEN now_at ELSE j.next_attempt_at END,
    error_code = CASE WHEN target = 'cancelled' THEN 'CANCELLED' ELSE j.error_code END,
    finished_at = CASE WHEN target = 'cancelled' THEN now_at ELSE j.finished_at END,
    expires_at = CASE WHEN target = 'cancelled' THEN now_at + interval '30 days' ELSE j.expires_at END,
    updated_at = now_at
  WHERE j.id = job.id;
  RETURN jsonb_build_object('status', 'ok', 'published', job.published_at IS NOT NULL);
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  existing biblib.library_jobs%ROWTYPE;
  active_id uuid;
  created_id uuid;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'library_job_create requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF NOT biblib.account_is_active(owner_id) THEN
    RETURN jsonb_build_object('status', 'inactive');
  END IF;
  -- Serializa las altas del mismo dueño: clave, límite y trabajo de portadas activo.
  PERFORM pg_advisory_xact_lock(hashtextextended('biblib.library_jobs:' || owner_id::text, 0));
  SELECT * INTO existing FROM biblib.library_jobs AS j WHERE j.user_id = owner_id AND j.kind = p_kind AND j.idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF existing.input_digest <> p_input_digest THEN
      RETURN jsonb_build_object('status', 'conflict');
    END IF;
    RETURN jsonb_build_object('status', 'existing', 'id', existing.id);
  END IF;
  IF p_kind = 'import' AND NOT EXISTS (SELECT 1 FROM biblib.import_previews AS preview WHERE preview.id = p_preview_id AND preview.user_id = owner_id) THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  -- Resúmenes terminados fuera de su retención.
  DELETE FROM biblib.library_jobs AS j WHERE j.user_id = owner_id AND j.finished_at IS NOT NULL AND j.expires_at <= now_at;
  IF p_kind = 'covers' THEN
    SELECT j.id INTO active_id FROM biblib.library_jobs AS j
    WHERE j.user_id = owner_id AND j.kind = 'covers' AND j.state IN ('queued', 'running', 'waiting_retry', 'paused') LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object('status', 'busy', 'id', active_id);
    END IF;
  END IF;
  IF (SELECT count(*) FROM biblib.library_jobs AS j WHERE j.user_id = owner_id AND j.state IN ('queued', 'running', 'waiting_retry', 'paused')) >= 5 THEN
    RETURN jsonb_build_object('status', 'limit');
  END IF;
  INSERT INTO biblib.library_jobs (user_id, kind, contract_version, idempotency_key, input_digest, preview_id, expected_revision, phase, next_attempt_at, expires_at)
  VALUES (owner_id, p_kind, 1, p_idempotency_key, p_input_digest, p_preview_id, p_expected_revision,
    CASE WHEN p_kind = 'import' THEN 'publish' ELSE 'covers' END, now_at, now_at + interval '7 days')
  RETURNING id INTO created_id;
  RETURN jsonb_build_object('status', 'created', 'id', created_id);
END;

DECLARE
  job record;
BEGIN
  SELECT j.user_id, j.state, j.lease_token, j.fencing_number, j.lease_until INTO job
  FROM biblib.library_jobs AS j WHERE j.id = p_job_id FOR UPDATE;
  IF NOT FOUND OR job.state <> 'running' OR job.lease_token IS DISTINCT FROM p_lease_token OR job.fencing_number <> p_fencing OR job.lease_until <= clock_timestamp() THEN
    RAISE EXCEPTION 'El lease del trabajo ya no es válido' USING ERRCODE = 'BJ001';
  END IF;
  IF NOT biblib.account_is_active(job.user_id) THEN
    RAISE EXCEPTION 'La cuenta del trabajo no está activa' USING ERRCODE = 'BJ002';
  END IF;
  RETURN job.user_id;
END;

DECLARE
  now_at timestamptz := clock_timestamp();
BEGIN
  UPDATE biblib.library_jobs AS j
  SET lease_until = now_at + greatest(1000, least(coalesce(p_lease_ms, 60000), 300000)) * interval '1 millisecond', updated_at = now_at
  WHERE j.id = p_job_id AND j.state = 'running' AND j.lease_token = p_lease_token AND j.fencing_number = p_fencing
    AND j.lease_until > now_at AND biblib.account_is_active(j.user_id);
  RETURN FOUND;
END;

DECLARE
  owner_id uuid := auth.uid();
  current_version uuid;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'library_snapshot_delete requiere una sesión' USING ERRCODE = '42501';
  END IF;
  PERFORM biblib.lock_library();
  SELECT s.version INTO current_version FROM biblib.library_snapshots AS s WHERE s.id = p_snapshot_id AND s.user_id = owner_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN 'not_found';
  END IF;
  IF current_version <> p_expected_version THEN
    RETURN 'conflict';
  END IF;
  DELETE FROM biblib.library_snapshots AS s WHERE s.id = p_snapshot_id AND s.user_id = owner_id;
  RETURN 'deleted';
END;

DECLARE
  removed integer;
BEGIN
  DELETE FROM biblib.library_snapshots AS s
  WHERE s.id IN (SELECT e.id FROM biblib.library_snapshots AS e WHERE e.expires_at <= clock_timestamp() ORDER BY e.expires_at LIMIT greatest(1, least(coalesce(p_limit, 100), 1000)));
  GET DIAGNOSTICS removed = ROW_COUNT;
  RETURN removed;
END;

DECLARE
  owner_id uuid := auth.uid();
  current_revision uuid;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'lock_library requiere una sesión' USING ERRCODE = '42501';
  END IF;
  PERFORM biblib.account_write_allowed();
  INSERT INTO biblib.library_state (user_id) VALUES (owner_id) ON CONFLICT (user_id) DO NOTHING;
  SELECT state.revision INTO current_revision FROM biblib.library_state AS state WHERE state.user_id = owner_id FOR UPDATE;
  PERFORM biblib.account_write_allowed();
  RETURN current_revision;
END;

BEGIN
  INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  VALUES ('biblib-media', 'biblib-media', false, 5242880, ARRAY['image/webp'])
  ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  DROP POLICY IF EXISTS "biblib_media_select_own" ON storage.objects;
  DROP POLICY IF EXISTS "biblib_media_insert_own" ON storage.objects;
  DROP POLICY IF EXISTS "biblib_media_delete_own" ON storage.objects;
  CREATE POLICY "biblib_media_select_own" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
    USING (bucket_id = 'biblib-media' AND biblib.media_object_access(name, 'select'));
  CREATE POLICY "biblib_media_insert_own" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
    WITH CHECK (bucket_id = 'biblib-media' AND biblib.media_object_access(name, 'insert'));
  CREATE POLICY "biblib_media_delete_own" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated
    USING (bucket_id = 'biblib-media' AND biblib.media_object_access(name, 'delete'));
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  new_id uuid := gen_random_uuid();
  key text;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'media_asset_begin_upload requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('avatar', 'location', 'evidence') THEN
    RAISE EXCEPTION 'Tipo de imagen no válido' USING ERRCODE = '22023';
  END IF;
  PERFORM biblib.account_write_allowed();
  IF NOT biblib.account_is_active(owner_id) THEN
    RETURN jsonb_build_object('status', 'inactive');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('biblib.media_assets:' || owner_id::text, 0));
  IF (SELECT count(*) FROM biblib.media_assets AS a WHERE a.user_id = owner_id AND a.state = 'quarantine' AND a.expires_at > now_at) >= 5 THEN
    RETURN jsonb_build_object('status', 'quota', 'quota', 'quarantine');
  END IF;
  IF (SELECT count(*) FROM biblib.media_assets AS a WHERE a.user_id = owner_id AND a.state = 'ready') >= 500
    OR (SELECT coalesce(sum(a.bytes), 0) FROM biblib.media_assets AS a WHERE a.user_id = owner_id AND a.state = 'ready') >= 209715200 THEN
    RETURN jsonb_build_object('status', 'quota', 'quota', 'stored');
  END IF;
  key := owner_id::text || '/' || p_kind || '/' || new_id::text;
  INSERT INTO biblib.media_assets (id, user_id, kind, state, storage_key, expires_at, created_at, updated_at)
  VALUES (new_id, owner_id, p_kind, 'quarantine', key, now_at + interval '15 minutes', now_at, now_at);
  RETURN jsonb_build_object('status', 'created', 'asset_id', new_id, 'storage_key', key);
END;

DECLARE
  owner_id uuid := auth.uid();
  asset biblib.media_assets%ROWTYPE;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'media_asset_discard requiere una sesión' USING ERRCODE = '42501';
  END IF;
  PERFORM biblib.account_write_allowed();
  SELECT * INTO asset FROM biblib.media_assets AS a WHERE a.id = p_asset_id AND a.user_id = owner_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  IF EXISTS (SELECT 1 FROM biblib.profiles AS p WHERE p.user_id = owner_id AND p.avatar_asset_id = asset.id)
    OR EXISTS (SELECT 1 FROM biblib.locations AS l WHERE l.user_id = owner_id AND l.photo_asset_id = asset.id)
    OR EXISTS (SELECT 1 FROM biblib.bibliographic_evidence AS e WHERE e.user_id = owner_id AND e.photo_asset_id = asset.id) THEN
    RETURN jsonb_build_object('status', 'referenced');
  END IF;
  DELETE FROM biblib.media_assets AS a WHERE a.id = asset.id;
  RETURN jsonb_build_object('status', 'discarded', 'storage_key', asset.storage_key);
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  max_rows integer := greatest(1, least(coalesce(p_limit, 100), 1000));
  grace interval := greatest(0, coalesce(p_grace_seconds, 86400)) * interval '1 second';
  assets jsonb;
  objects jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'owner', c.user_id, 'key', c.storage_key, 'reason', c.reason)), '[]'::jsonb) INTO assets
  FROM (
    SELECT a.id, a.user_id, a.storage_key, CASE WHEN a.state = 'quarantine' THEN 'quarantine' ELSE 'unreferenced' END AS reason
    FROM biblib.media_assets AS a
    WHERE (p_owner IS NULL OR a.user_id = p_owner) AND (
      (a.state = 'quarantine' AND a.expires_at <= now_at)
      OR (a.state = 'ready' AND a.updated_at <= now_at - grace
        AND NOT EXISTS (SELECT 1 FROM biblib.profiles AS p WHERE p.user_id = a.user_id AND p.avatar_asset_id = a.id)
        AND NOT EXISTS (SELECT 1 FROM biblib.locations AS l WHERE l.user_id = a.user_id AND l.photo_asset_id = a.id)
        AND NOT EXISTS (SELECT 1 FROM biblib.bibliographic_evidence AS e WHERE e.user_id = a.user_id AND e.photo_asset_id = a.id)
        AND NOT EXISTS (SELECT 1 FROM biblib.library_snapshot_chunks AS sc WHERE sc.user_id = a.user_id AND sc.kind IN ('books', 'locations')
          AND strpos(sc.payload::text, a.id::text) > 0)))
    ORDER BY a.updated_at
    LIMIT max_rows
  ) AS c;
  SELECT coalesce(jsonb_agg(jsonb_build_object('owner', split_part(o.name, '/', 1), 'key', o.name)), '[]'::jsonb) INTO objects
  FROM (
    SELECT so.name FROM storage.objects AS so
    WHERE so.bucket_id = 'biblib-media' AND (p_owner IS NULL OR so.name LIKE p_owner::text || '/%')
      AND so.created_at <= now_at - interval '10 minutes'
      AND NOT EXISTS (SELECT 1 FROM biblib.media_assets AS a WHERE a.storage_key = so.name)
    ORDER BY so.created_at
    LIMIT max_rows
  ) AS o;
  RETURN jsonb_build_object('assets', assets, 'objects', objects);
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  grace interval := greatest(0, coalesce(p_grace_seconds, 86400)) * interval '1 second';
  keys text[];
BEGIN
  PERFORM 1 FROM biblib.media_assets AS a WHERE a.id = ANY(p_ids) AND (p_owner IS NULL OR a.user_id = p_owner) FOR UPDATE;
  WITH removed AS (
    DELETE FROM biblib.media_assets AS a
    WHERE a.id = ANY(p_ids) AND (p_owner IS NULL OR a.user_id = p_owner) AND (
      (a.state = 'quarantine' AND a.expires_at <= now_at)
      OR (a.state = 'ready' AND a.updated_at <= now_at - grace
        AND NOT EXISTS (SELECT 1 FROM biblib.profiles AS p WHERE p.user_id = a.user_id AND p.avatar_asset_id = a.id)
        AND NOT EXISTS (SELECT 1 FROM biblib.locations AS l WHERE l.user_id = a.user_id AND l.photo_asset_id = a.id)
        AND NOT EXISTS (SELECT 1 FROM biblib.bibliographic_evidence AS e WHERE e.user_id = a.user_id AND e.photo_asset_id = a.id)
        AND NOT EXISTS (SELECT 1 FROM biblib.library_snapshot_chunks AS sc WHERE sc.user_id = a.user_id AND sc.kind IN ('books', 'locations')
          AND strpos(sc.payload::text, a.id::text) > 0)))
    RETURNING a.storage_key
  )
  SELECT coalesce(array_agg(r.storage_key), '{}'::text[]) INTO keys FROM removed AS r;
  RETURN keys;
END;

DECLARE
  owner_id uuid := auth.uid();
  now_at timestamptz := clock_timestamp();
  asset biblib.media_assets%ROWTYPE;
  max_bytes integer;
  max_side integer;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'media_asset_register requiere una sesión' USING ERRCODE = '42501';
  END IF;
  PERFORM biblib.account_write_allowed();
  SELECT * INTO asset FROM biblib.media_assets AS a WHERE a.id = p_asset_id AND a.user_id = owner_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  IF NOT biblib.account_is_active(owner_id) THEN
    RETURN jsonb_build_object('status', 'inactive');
  END IF;
  IF asset.state <> 'quarantine' OR asset.expires_at <= now_at THEN
    RETURN jsonb_build_object('status', 'stale');
  END IF;
  max_bytes := CASE WHEN asset.kind = 'avatar' THEN 1048576 ELSE 5242880 END;
  max_side := CASE WHEN asset.kind = 'avatar' THEN 1024 ELSE 4096 END;
  IF p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$' OR p_bytes IS NULL OR p_bytes < 1 OR p_bytes > max_bytes
    OR p_width IS NULL OR p_width < 1 OR p_width > max_side OR p_height IS NULL OR p_height < 1 OR p_height > max_side THEN
    RETURN jsonb_build_object('status', 'invalid');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM storage.objects AS o WHERE o.bucket_id = 'biblib-media' AND o.name = asset.storage_key AND (o.metadata->>'size')::bigint = p_bytes) THEN
    RETURN jsonb_build_object('status', 'missing_object');
  END IF;
  UPDATE biblib.media_assets AS a SET state = 'ready', sha256 = p_sha256, mime = 'image/webp', bytes = p_bytes, width = p_width, height = p_height,
    expires_at = NULL, version = gen_random_uuid(), updated_at = now_at
  WHERE a.id = asset.id;
  RETURN jsonb_build_object('status', 'ready', 'asset_id', asset.id);
END;

DECLARE
  owner_id uuid := auth.uid();
  parts text[];
  asset biblib.media_assets%ROWTYPE;
BEGIN
  IF owner_id IS NULL OR p_name IS NULL OR p_action IS NULL OR p_action NOT IN ('select', 'insert', 'delete') THEN
    RETURN false;
  END IF;
  parts := string_to_array(p_name, '/');
  IF coalesce(array_length(parts, 1), 0) <> 3 OR parts[1] <> owner_id::text OR parts[2] NOT IN ('avatar', 'location', 'evidence')
    OR parts[3] !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN false;
  END IF;
  SELECT * INTO asset FROM biblib.media_assets AS a WHERE a.id = parts[3]::uuid AND a.user_id = owner_id AND a.kind = parts[2];
  IF NOT FOUND THEN
    -- Objeto propio sin fila (subida descartada o asset ya retirado): el dueño lo ve y, con cuenta activa, lo retira
    -- (la API de Storage borra con RETURNING, que exige verlo). Nunca se sube sin fila.
    RETURN p_action = 'select' OR (p_action = 'delete' AND biblib.account_is_active(owner_id));
  END IF;
  IF p_action = 'select' THEN
    RETURN true;
  END IF;
  IF p_action = 'delete' THEN
    RETURN asset.state = 'quarantine' AND biblib.account_is_active(owner_id);
  END IF;
  RETURN asset.state = 'quarantine' AND asset.expires_at > clock_timestamp() AND biblib.account_is_active(owner_id);
END;

BEGIN
  DELETE FROM biblib.editions AS e
  USING (SELECT DISTINCT p.user_id, p.edition_id FROM previous AS p) AS gone
  WHERE e.user_id = gone.user_id AND e.id = gone.edition_id
    AND NOT EXISTS (SELECT 1 FROM biblib.copies AS c WHERE c.user_id = e.user_id AND c.edition_id = e.id);
  RETURN NULL;
END;

BEGIN
  DELETE FROM biblib.works AS w
  USING (SELECT DISTINCT p.user_id, p.work_id FROM previous AS p WHERE p.work_id IS NOT NULL) AS gone
  WHERE w.user_id = gone.user_id AND w.id = gone.work_id
    AND NOT EXISTS (SELECT 1 FROM biblib.editions AS e WHERE e.user_id = w.user_id AND e.work_id = w.id);
  RETURN NULL;
END;

DECLARE
  owners uuid[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    owners := ARRAY[NEW.user_id];
  ELSIF TG_OP = 'DELETE' THEN
    owners := ARRAY[OLD.user_id];
  ELSE
    owners := ARRAY[NEW.user_id, OLD.user_id];
  END IF;
  INSERT INTO biblib.library_state AS state (user_id, rotated_xact)
  SELECT DISTINCT owner_id, pg_current_xact_id() FROM unnest(owners) AS owner_id
  WHERE EXISTS (SELECT 1 FROM auth.users AS account WHERE account.id = owner_id)
  ON CONFLICT (user_id) DO UPDATE
    SET revision = gen_random_uuid(), rotated_xact = excluded.rotated_xact, updated_at = now()
    WHERE state.rotated_xact IS DISTINCT FROM excluded.rotated_xact;
  RETURN NULL;
END;

BEGIN
  IF value IS NULL OR jsonb_typeof(value) <> 'object' THEN RETURN false; END IF;
  IF NOT (value ?& ARRAY['status','shelf','sort','view','pageSize'])
    OR (value - ARRAY['q','status','shelf','sort','view','pageSize']) <> '{}'::jsonb THEN RETURN false; END IF;
  IF value ? 'q' AND (jsonb_typeof(value->'q') <> 'string' OR length(value->>'q') > 500) THEN RETURN false; END IF;
  IF jsonb_typeof(value->'status') <> 'string' OR value->>'status' NOT IN ('all','read','reading','unread','to-read') THEN RETURN false; END IF;
  IF jsonb_typeof(value->'shelf') <> 'string' OR (value->>'shelf' <> 'all' AND value->>'shelf' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') THEN RETURN false; END IF;
  IF jsonb_typeof(value->'sort') <> 'string' OR value->>'sort' NOT IN ('title','-title','author','-author','pages','-pages','date','-date','status','-status') THEN RETURN false; END IF;
  IF jsonb_typeof(value->'view') <> 'string' OR value->>'view' NOT IN ('table','grid') THEN RETURN false; END IF;
  IF jsonb_typeof(value->'pageSize') <> 'number' THEN RETURN false; END IF;
  RETURN (value->>'pageSize')::numeric BETWEEN 10 AND 100 AND trunc((value->>'pageSize')::numeric) = (value->>'pageSize')::numeric;
END;

DECLARE
  total integer;
BEGIN
  IF NEW.page_to IS NULL OR (TG_OP = 'UPDATE' AND NEW.page_to IS NOT DISTINCT FROM OLD.page_to AND NEW.cycle_id IS NOT DISTINCT FROM OLD.cycle_id) THEN
    RETURN NEW;
  END IF;
  SELECT e.number_of_pages INTO total
  FROM biblib.reading_cycles AS r
  JOIN biblib.copies AS c ON c.user_id = r.user_id AND c.id = r.copy_id
  JOIN biblib.editions AS e ON e.user_id = c.user_id AND e.id = c.edition_id
  WHERE r.user_id = NEW.user_id AND r.id = NEW.cycle_id;
  IF total > 0 AND NEW.page_to > total THEN
    RAISE EXCEPTION 'La página % supera el total conocido de la edición (%)', NEW.page_to, total USING ERRCODE = 'BR001';
  END IF;
  RETURN NEW;
END;

DECLARE
  owner_id uuid := auth.uid();
  found_cycle biblib.reading_cycles%ROWTYPE;
  next_number integer;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'reading_cycle_start requiere una sesión' USING ERRCODE = '42501';
  END IF;
  PERFORM biblib.account_write_allowed();
  PERFORM pg_advisory_xact_lock(hashtextextended(format('biblib.%s:%s:%s', 'reading_cycles', owner_id, p_copy_id), 0));
  IF NOT EXISTS (SELECT 1 FROM biblib.copies AS c WHERE c.user_id = owner_id AND c.id = p_copy_id) THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  SELECT * INTO found_cycle FROM biblib.reading_cycles AS r WHERE r.user_id = owner_id AND r.copy_id = p_copy_id AND r.status IN ('reading', 'paused');
  IF FOUND THEN
    RETURN jsonb_build_object('status', 'open', 'cycle_id', found_cycle.id, 'cycle_number', found_cycle.cycle_number, 'version', found_cycle.version);
  END IF;
  SELECT coalesce(max(r.cycle_number), 0) + 1 INTO next_number FROM biblib.reading_cycles AS r WHERE r.user_id = owner_id AND r.copy_id = p_copy_id;
  INSERT INTO biblib.reading_cycles (user_id, copy_id, cycle_number, status, started_at)
  VALUES (owner_id, p_copy_id, next_number, 'reading', p_started_at)
  RETURNING * INTO found_cycle;
  RETURN jsonb_build_object('status', 'started', 'cycle_id', found_cycle.id, 'cycle_number', found_cycle.cycle_number, 'version', found_cycle.version);
END;

DECLARE
  owner_id uuid := auth.uid();
  found_loan biblib.loans%ROWTYPE;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'loan_open requiere una sesión' USING ERRCODE = '42501';
  END IF;
  PERFORM biblib.account_write_allowed();
  PERFORM pg_advisory_xact_lock(hashtextextended(format('biblib.%s:%s:%s', 'loans', owner_id, p_copy_id), 0));
  IF NOT EXISTS (SELECT 1 FROM biblib.copies AS c WHERE c.user_id = owner_id AND c.id = p_copy_id) THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  SELECT * INTO found_loan FROM biblib.loans AS l WHERE l.user_id = owner_id AND l.copy_id = p_copy_id AND l.returned_on IS NULL;
  IF FOUND THEN
    RETURN jsonb_build_object('status', 'active', 'loan_id', found_loan.id, 'borrower_label', found_loan.borrower_label, 'loaned_on', found_loan.loaned_on, 'version', found_loan.version);
  END IF;
  INSERT INTO biblib.loans (user_id, copy_id, borrower_label, loaned_on, due_on, note)
  VALUES (owner_id, p_copy_id, p_borrower_label, p_loaned_on, p_due_on, p_note)
  RETURNING * INTO found_loan;
  RETURN jsonb_build_object('status', 'opened', 'loan_id', found_loan.id, 'version', found_loan.version);
END;

DECLARE
  owner_id uuid := auth.uid();
  found_cycle biblib.reading_cycles%ROWTYPE;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'reading_cycle_close requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('finished', 'abandoned') THEN
    RAISE EXCEPTION 'Estado de cierre no válido' USING ERRCODE = '22023';
  END IF;
  PERFORM biblib.account_write_allowed();
  SELECT * INTO found_cycle FROM biblib.reading_cycles AS r WHERE r.user_id = owner_id AND r.id = p_cycle_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  IF found_cycle.status IN ('finished', 'abandoned') THEN
    RETURN jsonb_build_object('status', 'already_closed', 'cycle_status', found_cycle.status, 'finished_at', found_cycle.finished_at, 'version', found_cycle.version);
  END IF;
  IF found_cycle.version IS DISTINCT FROM p_expected_version THEN
    RETURN jsonb_build_object('status', 'conflict', 'version', found_cycle.version);
  END IF;
  UPDATE biblib.reading_cycles AS r SET status = p_status, finished_at = p_finished_at, updated_at = clock_timestamp()
  WHERE r.user_id = owner_id AND r.id = p_cycle_id
  RETURNING * INTO found_cycle;
  RETURN jsonb_build_object('status', 'closed', 'version', found_cycle.version);
END;

DECLARE
  owner_id uuid := auth.uid();
  found_loan biblib.loans%ROWTYPE;
BEGIN
  IF owner_id IS NULL THEN
    RAISE EXCEPTION 'loan_return requiere una sesión' USING ERRCODE = '42501';
  END IF;
  IF p_returned_on IS NULL THEN
    RAISE EXCEPTION 'La devolución exige una fecha' USING ERRCODE = '22023';
  END IF;
  PERFORM biblib.account_write_allowed();
  SELECT * INTO found_loan FROM biblib.loans AS l WHERE l.user_id = owner_id AND l.id = p_loan_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;
  IF found_loan.returned_on IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'already_returned', 'returned_on', found_loan.returned_on, 'version', found_loan.version);
  END IF;
  IF found_loan.version IS DISTINCT FROM p_expected_version THEN
    RETURN jsonb_build_object('status', 'conflict', 'version', found_loan.version);
  END IF;
  UPDATE biblib.loans AS l SET returned_on = p_returned_on, updated_at = clock_timestamp()
  WHERE l.user_id = owner_id AND l.id = p_loan_id
  RETURNING * INTO found_loan;
  RETURN jsonb_build_object('status', 'returned', 'version', found_loan.version);
END;

DECLARE
  now_at timestamptz := clock_timestamp();
  target text;
  token text;
BEGIN
  -- Misma condición que library_job_claim para el ejecutor sin sesión: sin pasos reclamables no hay petición.
  IF NOT EXISTS (
    SELECT 1 FROM biblib.library_jobs AS j
    WHERE j.kind <> 'cover_asset' AND j.state IN ('queued', 'running', 'waiting_retry') AND j.next_attempt_at <= now_at
      AND (j.state <> 'running' OR j.lease_until <= now_at)
  ) THEN
    RETURN false;
  END IF;
  IF to_regclass('vault.decrypted_secrets') IS NULL OR to_regnamespace('net') IS NULL THEN
    RETURN false;
  END IF;
  SELECT s.decrypted_secret INTO target FROM vault.decrypted_secrets AS s WHERE s.name = 'biblib_jobs_runner_url';
  SELECT s.decrypted_secret INTO token FROM vault.decrypted_secrets AS s WHERE s.name = 'biblib_jobs_runner_token';
  -- El token nunca viaja sin TLS.
  IF target IS NULL OR token IS NULL OR target !~ '^https://[^/]+/api/internal/jobs/run$' THEN
    RETURN false;
  END IF;
  PERFORM net.http_post(url := target, headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || token), timeout_milliseconds := 60000);
  RETURN true;
END;
